package org.wonderloop.app.ui

/**
 * 4 pre-packaged child-style crayon drawings (448x448 JPEG) so the full flow can be tried on a Fire TV
 * or emulator without a phone. Generated as SVG crayon sketches; each is ~8 KB.
 */
